/* prog21_date_validator.c
 * Reimplementation of the original binary's observable behaviour.
 * The program validates a date supplied as the first command‑line
 * argument.  Accepted format: YYYY/MM/DD (exactly ten characters).
 * It prints "VALID" for a correct calendar date, otherwise "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

/* Return true if the given year is a leap year in the Gregorian calendar */
static bool is_leap(int year)
{
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

/* Return true if the string matches the pattern YYYY/MM/DD and represents
   a real calendar date. */
static bool check_date(const char *s)
{
    /* Length must be exactly 10 */
    if (strlen(s) != 10)
        return false;

    /* Positions 4 and 7 must be '/' */
    if (s[4] != '/' || s[7] != '/')
        return false;

    /* All other characters must be decimal digits */
    for (int i = 0; i < 10; ++i) {
        if (i == 4 || i == 7) continue;
        if (s[i] < '0' || s[i] > '9')
            return false;
    }

    /* Convert the three fields */
    int year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
                (s[2] - '0') * 10   + (s[3] - '0');

    int month = (s[5] - '0') * 10 + (s[6] - '0');
    int day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Basic range checks */
    if (month < 1 || month > 12)
        return false;
    if (day < 1)
        return false;

    /* Days per month, index 1‑12 (0 unused) */
    static const int days_in_month[13] = {
        0, 31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    int max_day = days_in_month[month];
    if (month == 2 && is_leap(year))
        max_day = 29;

    return day <= max_day;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        puts("INVALID");
        return 0;
    }

    if (check_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
